def compute(vars):
    industrial_packaging_sales = vars["v1"]
    containerboard_sales = vars["v2"]

    if industrial_packaging_sales == 0:
        return None

    value = containerboard_sales / industrial_packaging_sales * 100
    return {
        "value": value,
        "trace": {
            "industrial_packaging_sales": industrial_packaging_sales,
            "containerboard_sales": containerboard_sales,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
